/* ===== Screens, part two ===== */
/* ---------- 7. Diplomatic Affairs ---------- */
SCREENS.diplomacy = () => {
  const act = activeNegs(), done = ST.negotiations.filter(n => n.status !== 'active').slice().reverse();
  const civs = ST.civs.filter(c => c.discovered && c.kind !== 'capital');
  const stances = [['concede', 'Offer a concession', 'CC 150M; large progress, tension falls'], ['hold', 'Hold position', 'Steady progress, slight tension'], ['press', 'Press firmly', 'Volatile progress, tension rises sharply'], ['mediate', 'Ask Elyndor to mediate', 'Good progress, tension falls; Council efficiency −0.3']];
  const negCard = n => plate(esc(n.title), `<div class="row" style="margin:-6px 0 10px"><span class="mono goldt">${n.id}</span><span class="pill">${n.parties.map(id => esc(civName(ST, id))).join(' · ')}</span><span class="faint" style="font-size:12px">Round ${n.round} of ${n.maxRounds} · next round ${esc(fmtDate(n.nextRound))}</span></div>
    <div class="grid g2" style="gap:12px"><div><div class="spread" style="font-size:12px"><span>Agreement</span><span class="num">${Math.round(n.progress)}%</span></div>${meter(n.progress, 'blue')}</div><div><div class="spread" style="font-size:12px"><span>Tension</span><span class="num">${Math.round(n.tension)}%</span></div>${meter(n.tension, n.tension > 70 ? 'bad' : 'warn')}</div></div>
    <div class="eyebrow" style="margin-top:12px">Instructions for the next round</div><div class="stack" style="gap:6px;margin-top:6px">${stances.map(([k, l, d]) => `<label class="row" style="gap:8px;font-size:13px;cursor:pointer"><input type="radio" name="st-${n.id}" data-chg="stance" data-id="${n.id}" value="${k}" id="st-${n.id}-${k}" ${n.stance === k ? 'checked' : ''}><span><b>${l}</b> <span class="muted">${d}</span></span></label>`).join('')}</div>
    <div class="btnrow" style="margin-top:10px"><button class="btn sm" data-act="negNow" data-id="${n.id}">Hold this round now</button></div>
    <div class="sep"></div><div class="muted" style="font-size:12px">${n.log.slice(-4).map(esc).join('<br>')}</div>`);
  const treaties = ST.laws.filter(l => l.type === 'treaty');
  return `<div class="screen">${head('Diplomatic Affairs', 'Concord Station', 'Negotiations develop over several rounds, one each week. Set the Crown’s stance before each round.', '')}
  <div class="grid g-side"><div class="stack" style="gap:14px">${act.length ? act.map(negCard).join('') : plate('', '<div class="empty">No negotiations in progress.</div>')}</div>
  <div class="stack" style="gap:14px">${plate('Prepare a diplomatic summit', `<p class="muted" style="margin-top:0;font-size:13px">Host two civilisations at Concord Station (CC 300M). The summit opens a negotiation with a head start.</p><label class="f">First party<select id="sumA">${civs.map(c => `<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="f" style="margin-top:8px">Second party<select id="sumB">${civs.map((c, i) => `<option value="${c.id}" ${i === 1 ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label><label class="f" style="margin-top:8px">Topic<input type="text" id="sumTopic" value="Shared trade lanes and peaceful cooperation"></label><button class="btn primary" style="margin-top:10px" data-act="summit">Host summit</button>`)}
  ${plate('Relations at a glance', barList(civs.map(c => ({label:c.name, v:c.rel, cls:c.rel < 45 ? 'bad' : c.rel < 65 ? 'warn' : ''})), {fmt:v => fmt(v)}))}
  ${plate('Treaties', treaties.length ? treaties.map(t => `<div class="li"><span class="mono goldt">${t.id}</span><div class="grow"><h4>${esc(t.title)}</h4><p>${statusPill(t.status)}</p></div></div>`).join('') : '<div class="empty">No treaties concluded yet.</div>')}
  ${plate('Concluded and failed', done.length ? done.slice(0, 10).map(n => `<div class="li"><div class="grow"><h4>${esc(n.title)}</h4><p>${n.parties.map(id => esc(civName(ST, id))).join(' · ')}</p></div>${statusPill(n.status)}</div>`).join('') : '<div class="empty">None yet.</div>')}</div></div></div>`;
};

/* ---------- 8. Cosmic Treasury ---------- */
SCREENS.treasury = () => {
  const T = ST.treasury, rev = projectedRevenue(ST), rc = recurringCosts(ST);
  const revT = Object.values(rev).reduce((a, b) => a + b, 0), expT = budgetTotal(ST) + rc.laws + rc.edu;
  const hist = T.hist;
  const chart = lineChart([{name:'Balance', color:'#D4AF37', area:true, data:hist.map(h => [h.day, h.balance])}], {label:'Treasury balance over time', h:180});
  const chart2 = lineChart([{name:'Revenue', color:'#62C893', data:hist.map(h => [h.day, h.revenue])}, {name:'Expenditure', color:'#E5705F', data:hist.map(h => [h.day, h.expense])}, {name:'Reserve', color:'#7FA3F5', data:hist.map(h => [h.day, h.reserve])}], {label:'Monthly revenue, expenditure and reserve', h:180});
  const budgetRows = BUDGET_CATS.map(b => `<tr><td>${esc(b.label)}</td><td class="r faint">${fmt(b.base)}</td><td class="r"><input type="number" min="0" max="20000" step="10" id="bud-${b.key}" value="${T.budget[b.key]}" style="width:100px;text-align:right" aria-label="${esc(b.label)} monthly allocation"></td><td style="font-size:12px" class="muted">${Object.keys(b.eff).map(k => IND_SHORT[k]).join(', ') || 'Builds the emergency reserve'}</td></tr>`).join('');
  const proj = ST.projects.slice().sort((a, b) => (a.status === 'active' ? 0 : 1) - (b.status === 'active' ? 0 : 1) || b.started - a.started);
  const lf = UI.filter.ledger || 'all';
  const led = T.ledger.filter(l => lf === 'all' || l.type === lf).slice(0, 60);
  return `<div class="screen">${head('Cosmic Treasury', 'Cosmic Credits', 'All figures are in millions of Cosmic Credits (CC). Contributions from member civilisations are voluntary.', `<button class="btn" data-act="treasuryReport">Generate treasury report</button>`)}
  ${plate('', `<div class="statline"><div><small>Balance</small><b>${fmtCC(T.balance)}</b></div><div><small>Emergency reserve</small><b>${fmtCC(T.reserve)}</b></div><div><small>Projected revenue / month</small><b class="good">${fmtCC(revT)}</b></div><div><small>Planned spending / month</small><b class="bad">${fmtCC(expT)}</b></div><div><small>Net / month</small><b class="${revT - expT >= 0 ? 'good' : 'bad'}">${revT - expT >= 0 ? '+' : '−'}${fmtCC(Math.abs(revT - expT)).replace('CC ', 'CC ')}</b></div><div><small>Surplus months</small><b>${ST.stats.positiveMonths}</b></div></div>`)}
  <div class="grid g2">${plate('Reserves', chart)}${plate('Revenue and expenditure', chart2)}</div>
  <div class="grid g2">
    ${plate('Annual budget', `<p class="muted" style="margin-top:0;font-size:13px">Monthly allocations. Funding above the baseline improves the related indicators each month; cutting below it erodes them. The year’s budget is 12 times these figures: ${fmtCC(budgetTotal(ST) * 12)}.</p><div class="tablewrap"><table><thead><tr><th>Category</th><th class="r">Baseline</th><th class="r">Allocation</th><th>Affects</th></tr></thead><tbody>${budgetRows}</tbody></table></div><div class="spread" style="margin-top:10px"><span class="muted" style="font-size:12.5px">Also each month: laws in force ${fmtCC(rc.laws)} · COSMOS–EDU ${fmtCC(rc.edu)}</span><button class="btn primary" data-act="applyBudget">Review and apply budget</button></div>`)}
    <div class="stack" style="gap:14px">${plate('Revenue sources (projected this month)', barList(Object.entries(rev).map(([k, v]) => ({label:REVENUE_CATS[k], v})), {fmt:v => fmtCC(v)}))}
    ${plate('Allocate emergency funds', `<p class="muted" style="margin-top:0;font-size:13px">Move funds from the general balance into the emergency reserve. Emergency responses draw on the reserve first.</p><div class="row" style="align-items:flex-end"><label class="f" style="flex:1">Amount (CC M)<input type="number" min="1" step="50" id="reserveAmt" value="500"></label><button class="btn primary" data-act="toReserve">Allocate</button></div>`)}</div></div>
  ${plate('Finance a major project', `<div class="grid g3">${MAJOR_PROJECTS.map(pj => { const active = ST.projects.some(x => x.key === pj.key && x.status === 'active'); const locked = pj.req && ST.research[pj.req.track] < pj.req.lvl; return `<div class="plate flat" style="padding:12px"><div class="spread"><b>${esc(pj.name)}</b><span class="num goldt">${fmtCC(pj.cost)}</span></div><p class="muted" style="font-size:12.5px;margin:4px 0 6px">${esc(pj.desc)} ${pj.duration} days.</p>${effChips(ST, pj.eff)}<button class="btn sm ${active || locked ? '' : 'primary'}" style="margin-top:8px" data-act="finance" data-key="${pj.key}" ${active || locked ? 'disabled' : ''}>${active ? 'Under way' : locked ? 'Research required' : 'Finance'}</button></div>`; }).join('')}</div>`)}
  ${plate('Projects', proj.length ? `<div class="tablewrap"><table><thead><tr><th>ID</th><th>Project</th><th>Category</th><th class="r">Cost</th><th style="min-width:140px">Progress</th><th>Status</th></tr></thead><tbody>${proj.slice(0, 40).map(p => `<tr><td class="mono">${p.id}</td><td>${esc(p.name)}</td><td>${esc(cap(p.cat))}</td><td class="r">${fmtCC(p.cost)}</td><td>${meter(p.progress / p.duration * 100, 'blue')}<span class="faint num" style="font-size:11px">${Math.round(p.progress / p.duration * 100)}%</span></td><td>${p.status === 'complete' ? `<span class="pill good">Complete ${esc(fmtDateShort(p.completed))}</span>` : '<span class="pill blue">Active</span>'}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No projects.</div>')}
  ${plate('Ledger', `<div class="tabs" style="margin-bottom:8px">${[['all', 'All'], ['revenue', 'Revenue'], ['expense', 'Expenditure'], ['transfer', 'Transfers']].map(([k, l]) => `<button aria-selected="${lf === k}" data-act="filter" data-k="ledger" data-v="${k}">${l}</button>`).join('')}</div>${led.length ? `<div class="tablewrap"><table><thead><tr><th>Ref.</th><th>Date</th><th>Category</th><th>Memo</th><th class="r">Amount</th></tr></thead><tbody>${led.map(l => `<tr><td class="mono">${l.id}</td><td>${esc(fmtDateShort(l.day))}</td><td>${esc(REVENUE_CATS[l.cat] || (BUDGET_CATS.find(b => b.key === l.cat) || {label:cap(l.cat)}).label)}</td><td style="font-size:12.5px">${esc(l.memo)}</td><td class="r ${l.type === 'revenue' ? 'good' : l.type === 'expense' ? 'bad' : ''}">${l.type === 'revenue' ? '+' : '−'}${fmt(l.amount)}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No transactions yet. Advance time to the end of the month.</div>'}`)}
  </div>`;
};
function treasuryReportBody() {
  const T = ST.treasury, rev = projectedRevenue(ST), rc = recurringCosts(ST), h = T.hist.slice(-3);
  return `COSMIC TREASURY — COMPLETE REPORT\nPrepared for ${ST.canon.sovereign}, ${sovTitle(ST)}\nDate: ${fmtDate(ST.day)}\n\nBalance: ${fmtCC(T.balance)}\nEmergency reserve: ${fmtCC(T.reserve)}\n\nProjected monthly revenue:\n${Object.entries(rev).map(([k, v]) => `— ${REVENUE_CATS[k]}: ${fmtCC(v)}`).join('\n')}\n\nMonthly budget:\n${BUDGET_CATS.map(b => `— ${b.label}: ${fmtCC(T.budget[b.key])} (baseline ${fmtCC(b.base)})`).join('\n')}\n— Laws in force: ${fmtCC(rc.laws)}\n— COSMOS–EDU modules and scholarships: ${fmtCC(rc.edu)}\n\nRecent months:\n${h.map(x => `— ${fmtDateShort(x.day)}: revenue ${fmtCC(x.revenue)}, expenditure ${fmtCC(x.expense)}, closing balance ${fmtCC(x.balance)}`).join('\n') || '— No completed months yet.'}\n\nActive projects: ${ST.projects.filter(p => p.status === 'active').length}. Surplus months this reign: ${ST.stats.positiveMonths}.\n\nKaelith, Judge of Balance, notes: ${T.balance < 10000 ? 'Reserves are dangerously thin. Restraint is required.' : budgetTotal(ST) > Object.values(rev).reduce((a, b) => a + b, 0) ? 'Spending exceeds revenue. The treasury can absorb this for a time, but not forever.' : 'The accounts are in balance.'}`;
}

/* ---------- 9. Legislative Assembly ---------- */
SCREENS.legislature = () => {
  const tab = UI.tab.legislature || 'draft';
  const tabs = [['draft', 'Draft an instrument'], ['drafts', `Drafts (${ST.drafts.length})`], ['db', `Legal database (${ST.laws.length})`]];
  const locked = ST.rise && !ST.rise.crowned;
  let body = '';
  if (tab === 'draft') {
    const d = UI.draft || (UI.draft = {type:'act', title:'', text:'', impl:'', provisions:[], target:''});
    const rv = UI.review;
    body = `<div class="grid g-side">${plate('Draft', `${locked ? '<p class="pill warn">As a candidate you may draft, but you cannot enact.</p>' : ''}<div class="grid g2"><label class="f">Legal classification<select id="lawType" data-chg="draftField" data-f="type">${LAW_TYPES.map(t => `<option value="${t.key}" ${d.type === t.key ? 'selected' : ''}>${t.label}</option>`).join('')}</select></label><label class="f">Official title<input type="text" id="lawTitle" data-inp="draftField" data-f="title" value="${esc(d.title)}" placeholder="e.g. Cosmic Education Act"></label></div>
      ${d.type === 'treaty' ? `<label class="f" style="margin-top:8px">Treaty partner<select id="lawTarget" data-chg="draftField" data-f="target"><option value="">Choose a civilisation</option>${ST.civs.filter(c => c.discovered && c.kind !== 'capital').map(c => `<option value="${c.id}" ${d.target === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label>` : ''}
      ${d.amends ? `<p class="pill purple" style="margin-top:8px">Amends ${esc(d.amends)}</p>` : ''}
      <div class="eyebrow" style="margin-top:12px">Provisions</div><div class="stack" style="gap:6px;margin-top:6px">${PROVISIONS.map(P => `<label class="row" style="gap:8px;align-items:flex-start;font-size:13px;cursor:pointer"><input type="checkbox" data-chg="draftProv" value="${P.key}" id="prov-${P.key}" ${d.provisions.includes(P.key) ? 'checked' : ''}><span><b>${esc(P.label)}</b>${P.flags.length ? ' <span class="pill bad">Constitutional concern</span>' : ''}${P.cost ? ` <span class="pill">${fmtCC(P.cost)}/month</span>` : ''}<br><span class="muted">${esc(P.desc)}</span></span></label>`).join('')}</div>
      <label class="f" style="margin-top:12px">Full text<textarea id="lawText" data-inp="draftField" data-f="text" placeholder="Preamble and operative text">${esc(d.text)}</textarea></label>
      <label class="f" style="margin-top:8px">Implementation instructions<textarea id="lawImpl" data-inp="draftField" data-f="impl" placeholder="Which department implements it, and how" style="min-height:60px">${esc(d.impl)}</textarea></label>
      <div class="btnrow" style="margin-top:12px"><button class="btn" data-act="saveDraft">Save draft</button><button class="btn blue" data-act="review">Constitutional review</button><button class="btn primary" data-act="enact" ${locked ? 'disabled' : ''}>Sign and enact</button><button class="btn ghost" data-act="clearDraft">Clear</button></div>`)}
      ${plate('Constitutional review', rv ? `<p style="margin-top:0"><span class="pill ${rv.compatible ? 'good' : 'bad'}">${rv.compatible ? 'Compatible' : 'Conflicts found'}</span> <span class="muted" style="font-size:12.5px">Recurring cost ${fmtCC(rv.cost)}/month · ${rv.yes} of 12 judges in support${d.type === 'amend' ? ' (8 required for amendments)' : ''}</span></p>${rv.flags.map(f => `<div class="alert-row" style="margin-bottom:6px;font-size:13px"><b>Principle ${f.principle}</b> ${esc(PRINCIPLES[f.principle - 1])} <span class="muted">(${esc(f.provision)})</span></div>`).join('')}${rv.opinions.map(o => { const j = judges(ST).find(x => x.name === o.name); return `<div class="opinion">${sigil(o.name, j ? j.hue : 45, 30)}<div><div class="who">${esc(o.name)}</div><p>${esc(o.text)}</p></div></div>`; }).join('')}` : '<p class="muted" style="font-size:13px;margin-top:0">Request a review to see whether the draft is compatible with the Constitutional Principles before you enact it.</p><ol style="font-size:12.5px;padding-left:18px" class="muted">' + PRINCIPLES.map(p => `<li>${esc(p)}</li>`).join('') + '</ol>')}</div>`;
  } else if (tab === 'drafts') {
    body = plate('Saved drafts', ST.drafts.length ? ST.drafts.map(d => `<div class="li"><span class="mono goldt">${d.id}</span><div class="grow"><h4>${esc(d.title)}</h4><p>${esc((LAW_TYPES.find(t => t.key === d.type) || {}).label)} · ${d.provisions.length} provisions</p></div><div class="btnrow"><button class="btn sm" data-act="editDraft" data-id="${d.id}">Edit</button><button class="btn sm danger" data-act="delDraft" data-id="${d.id}">Discard</button></div></div>`).join('') : '<div class="empty">No drafts saved.</div>');
  } else {
    const q = (UI.filter.lawq || '').toLowerCase(), tf = UI.filter.lawt || '', sf = UI.filter.laws || '';
    const laws = ST.laws.filter(l => (!q || (l.id + ' ' + l.title + ' ' + l.text).toLowerCase().includes(q)) && (!tf || l.type === tf) && (!sf || l.status === sf)).slice().reverse();
    const sel = ST.laws.find(l => l.id === UI.sel.law);
    body = `<div class="row"><label class="f" style="flex:2 1 220px">Search<input type="search" id="lawSearch" data-inp="lawSearch" value="${esc(UI.filter.lawq || '')}" placeholder="Reference, title or text"></label><label class="f" style="flex:1 1 150px">Classification<select data-chg="lawFilter" data-k="lawt" id="lawTypeF"><option value="">All</option>${LAW_TYPES.map(t => `<option value="${t.key}" ${tf === t.key ? 'selected' : ''}>${t.label}</option>`).join('')}</select></label><label class="f" style="flex:1 1 140px">Status<select data-chg="lawFilter" data-k="laws" id="lawStatusF"><option value="">All</option>${['implementing','in force','amended','repealed','struck down','expired'].map(s => `<option ${sf === s ? 'selected' : ''}>${s}</option>`).join('')}</select></label></div>
    <div class="grid g-side">${plate('Instruments', laws.length ? `<div class="tablewrap"><table><thead><tr><th>Reference</th><th>Title</th><th>Status</th><th>Issued</th></tr></thead><tbody>${laws.map(l => `<tr class="click ${sel && sel.id === l.id ? 'sel' : ''}" data-act="sel" data-k="law" data-id="${l.id}"><td class="mono">${l.id}</td><td>${esc(l.title)}${l.flagged ? ' <span class="pill bad">Contested</span>' : ''}</td><td>${statusPill(l.status)}</td><td>${esc(fmtDateShort(l.issued))}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No instruments match.</div>')}
    ${sel ? plate(esc(sel.title), `<div class="row" style="margin:-6px 0 8px"><span class="mono goldt">${sel.id}</span>${statusPill(sel.status)}<span class="pill">${esc((LAW_TYPES.find(t => t.key === sel.type) || {}).label)}</span></div><p style="font-size:13.5px">${esc(sel.text || '—')}</p>${sel.provisions.length ? `<div class="eyebrow">Provisions</div><ul style="font-size:13px;padding-left:18px">${sel.provisions.map(k => `<li>${esc((PROVISIONS.find(p => p.key === k) || {label:k}).label)}</li>`).join('')}</ul>` : ''}${sel.status === 'implementing' ? `<p class="muted" style="font-size:12.5px">In force in ${sel.implLeft} days.</p>` : ''}${sel.sunsetAt ? `<p class="muted" style="font-size:12.5px">Sunset on ${esc(fmtDate(sel.sunsetAt))}.</p>` : ''}<div class="eyebrow">History</div><div class="muted" style="font-size:12.5px">${sel.history.map(esc).join('<br>')}</div><div class="btnrow" style="margin-top:10px">${(() => { const d = ST.documents.find(x => x.ref === sel.id); return d ? `<button class="btn sm" data-act="doc" data-id="${d.id}">View document</button>` : ''; })()}${['in force','implementing'].includes(sel.status) && sel.id !== 'ACT-0000' ? `<button class="btn sm" data-act="amendLaw" data-id="${sel.id}">Amend</button><button class="btn sm danger" data-act="repeal" data-id="${sel.id}">Repeal</button>` : ''}</div>`) : plate('', '<div class="empty">Select an instrument to read it.</div>')}</div>`;
  }
  return `<div class="screen">${head('Legislative Assembly', 'Acts, Orders and Charters', 'Draft instruments, submit them to constitutional review, and sign them under the Cosmic Seal. Policies take effect after an implementation period.')}
  <div class="tabs" role="tablist">${tabs.map(([k, l]) => `<button role="tab" aria-selected="${tab === k}" data-act="tab" data-scr="legislature" data-tab="${k}">${l}</button>`).join('')}</div>${body}</div>`;
};

/* ---------- 10. Scientific Research ---------- */
SCREENS.research = () => {
  const active = ST.projects.filter(p => p.special === 'research');
  const ch = ST.indHist.length > 1 ? lineChart([{name:'Scientific Advancement', color:'#7FA3F5', area:true, data:ST.indHist.map(h => [h.day, h.science])}], {min:0, max:100, h:150, label:'Scientific advancement'}) : '<div class="empty">History builds month by month.</div>';
  return `<div class="screen">${head('Scientific Research', 'The Forge and the Index', `Scientific Advancement stands at ${fmt(ST.ind.science)}. Research takes time and unlocks better responses across the simulation.`)}
  <div class="grid g3">${RESEARCH_TRACKS.map(t => { const lvl = ST.research[t.key], c = researchCost(ST, t.key), run = active.find(p => p.track === t.key && p.status === 'active'); return plate(esc(t.name), `<div class="spread"><span class="muted" style="font-size:12px">Level ${lvl} of 5</span><span class="goldt num">${'◆'.repeat(lvl)}${'◇'.repeat(5 - lvl)}</span></div><p style="font-size:13px">${esc(t.desc)}</p><p class="faint" style="font-size:12px">${esc(t.bonus)}</p>${run ? `<div style="margin:6px 0">${meter(run.progress / run.duration * 100, 'blue')}<span class="faint" style="font-size:11px">${esc(run.name)} · ${Math.round(run.progress / run.duration * 100)}%</span></div>` : ''}<button class="btn sm ${run || lvl >= 5 ? '' : 'primary'}" data-act="research" data-track="${t.key}" ${run || lvl >= 5 ? 'disabled' : ''}>${lvl >= 5 ? 'Complete' : run ? 'In progress' : `Fund level ${c.lvl} · ${fmtCC(c.cost)} · ${c.duration} days`}</button>`); }).join('')}
  ${plate('Scientific licensing', `<p style="font-size:13px;margin-top:0">Licensing revenue this month is projected at <b>${fmtCC(projectedRevenue(ST).licensing)}</b>, scaling with Scientific Advancement.${ST.laws.some(l => l.status === 'in force' && l.provisions.includes('open_science')) ? ' Open Science Licensing is in force, halving licence income.' : ''}</p>${ch}`)}</div>
  ${plate('Research centres', STATIONS.filter(s => s.type === 'research').map(s => `<div class="li"><div class="grow"><h4>${esc(s.name)}</h4><p>${esc(s.note)}</p></div><button class="btn sm ghost" data-act="mapSel" data-id="${s.id}">On the map</button></div>`).join(''))}</div>`;
};

/* ---------- 11. Cosmic Education (COSMOS–EDU) ---------- */
SCREENS.education = () => {
  const E = ST.edu, rc = recurringCosts(ST), ped = 1 - 0.1 * ST.research.pedagogy;
  const partners = ['Lumen Archive','Academy of the Crown','Veyari Crystal Libraries','Thalassine Song Schools'];
  const accessDone = ST.projects.some(p => p.special === 'access');
  return `<div class="screen">${head('Cosmic Education', 'COSMOS–EDU', 'Established under EARTH–DAIS–001, with Dhirubhai Ambani International School as the first pilot institution. Equal opportunity and accessibility for students with disabilities are founding commitments.')}
  ${plate('', `<div class="statline"><div><small>Educational accessibility</small><b>${fmt(ST.ind.education)}</b></div><div><small>Institutions</small><b>${E.institutions.length}</b></div><div><small>Students</small><b>${fmt(E.institutions.reduce((a, i) => a + i.students, 0))}</b></div><div><small>Scholarships</small><b>${fmt(E.scholarships)}</b></div><div><small>Programme cost / month</small><b>${fmtCC(rc.edu)}</b></div><div><small>Education budget / month</small><b>${fmtCC(ST.treasury.budget.education)}</b></div></div>`)}
  <div class="grid g-side">${plate('Institutions', `<div class="tablewrap"><table><thead><tr><th>Institution</th><th>Civilisation</th><th>Status</th><th class="r">Students</th></tr></thead><tbody>${E.institutions.map(i => `<tr><td>${esc(i.name)}${i.pilot ? ' <span class="pill gold">First pilot</span>' : ''}${i.accessible ? ' <span class="pill good">Accessible</span>' : ''}</td><td>${esc(civName(ST, i.civ))}</td><td>${esc(i.status)}</td><td class="r">${fmt(i.students)}</td></tr>`).join('')}</tbody></table></div>
    <div class="sep"></div><h3>Establish a new institution</h3><div class="row" style="align-items:flex-end;margin-top:8px"><label class="f" style="flex:2 1 200px">Institution name<input type="text" id="eduName" placeholder="e.g. Maris Tidal Academy"></label><label class="f" style="flex:1 1 150px">Civilisation<select id="eduCiv">${ST.civs.filter(c => c.discovered).map(c => `<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><button class="btn primary" data-act="eduExpand">Establish (${fmtCC(Math.round(700 * ped))}, 50 days)</button></div><p class="faint" style="font-size:12px">Institutions are established only with the host civilisation’s consent (relation 40 or higher).</p>`)}
  <div class="stack" style="gap:14px">${plate('Educational modules', `<div class="stack" style="gap:6px">${EDU_MODULES.map(m => `<label class="spread" style="font-size:13.5px;cursor:pointer"><span class="row" style="gap:8px"><input type="checkbox" data-chg="eduModule" value="${m.key}" id="mod-${m.key}" ${E.modules[m.key] ? 'checked' : ''}>${esc(m.name)}</span><span class="faint num" style="font-size:12px">${fmtCC(30 * ped)}/mo</span></label>`).join('')}</div><p class="faint" style="font-size:12px;margin-bottom:0">Each module raises Educational Accessibility monthly. Ethics strengthens legitimacy, Environmental responsibility the environment, and Exchanges trust.</p>`)}
  ${plate('Scholarships', `<div class="row" style="align-items:flex-end"><label class="f" style="flex:1">Funded scholarships<input type="number" min="0" step="50" id="schol" value="${E.scholarships}"></label><button class="btn primary" data-act="setSchol">Set</button></div><p class="faint" style="font-size:12px">${fmtCC(0.12 * ped)} per scholarship per month. Up to 2,000 scholarships raise accessibility.</p>`)}
  ${plate('Partnerships and research', `${partners.map(p => `<div class="spread" style="padding:5px 0"><span style="font-size:13.5px">${esc(p)}</span>${E.partnerships.includes(p) ? '<span class="pill good">Partner</span>' : `<button class="btn sm" data-act="eduPartner" data-p="${esc(p)}">Partner (CC 200M)</button>`}</div>`).join('')}<div class="sep"></div><div class="spread"><span style="font-size:13.5px">Universal accessibility programme</span>${accessDone ? '<span class="pill good">Funded</span>' : '<button class="btn sm primary" data-act="eduAccess">Fund (CC 650M)</button>'}</div><p class="faint" style="font-size:12px">Adapts every institution for students with disabilities.</p>`)}</div></div>
  ${plate('Founding record: EARTH–DAIS–001', `<p style="font-size:13.5px;margin:0">${esc((ST.archives.find(a => a.ref === 'EARTH–DAIS–001') || {body:''}).body)}</p>`)}</div>`;
};

/* ---------- 12. Earth Affairs ---------- */
SCREENS.earth = () => {
  const e = civById(ST, 'earth'), ec = earthCollectiveStatus(ST);
  const pets = ST.petitions.filter(p => p.civ === 'earth').slice().reverse();
  const acts = [['visit', 'Official visit to Earth', 'CC 150M · 5 days · Approval and Earth relation rise'], ['delegation', 'Invite the representatives of Earth', 'CC 100M · receives Earth’s delegates at the Tribunal'], ['science', 'Scientific cooperation programme', 'CC 600M · 60 days · requires Earth’s consent'], ['environment', 'Environmental assistance', 'CC 900M · 90 days · requires Earth’s consent'], ['exchange', 'Educational exchange', 'CC 200M · students exchange places']];
  return `<div class="screen">${head('Earth Affairs', 'Earth, an Independent Civilisation', 'The Sovereign’s Earthly identity and cosmic identity coexist. Earth keeps its own nations, laws and choices; the Crown cooperates and never governs.')}
  <div class="grid g-side"><div class="stack" style="gap:14px">${civPanel(e, true)}
  ${plate('Earth-origin petitions', pets.length ? pets.map(p => `<div class="li"><span class="mono goldt">${p.id}</span><div class="grow"><h4>${esc(p.title)}</h4><p>${esc(p.petitioner)}</p></div>${statusPill(p.status)}<button class="btn sm ghost" data-act="openPet" data-id="${p.id}">Open</button></div>`).join('') : '<div class="empty">No petitions from Earth at present.</div>')}</div>
  <div class="stack" style="gap:14px">${plate('Collective petition timer', `<div style="text-align:center"><div class="eyebrow">Next collective planetary petition</div><div style="font-family:var(--f-display);font-size:44px;color:var(--champ);line-height:1.1">Year ${ec.next}</div><div class="muted">${ec.eligible ? 'Earth may now submit a collective petition.' : `${fmt(ec.yearsLeft)} years remain`}</div></div><p class="faint" style="font-size:12px">Earth may submit one collective cosmic petition per millennium. Individual requests are always welcome.</p>`)}
  ${plate('Relations with Earth', acts.map(([k, l, d]) => `<div class="li"><div class="grow"><h4>${l}</h4><p>${d}</p></div><button class="btn sm primary" data-act="earth" data-a="${k}">Begin</button></div>`).join('') + `<p class="faint" style="font-size:12px">Visits: ${ST.earth.visits} · Delegations received: ${ST.earth.delegations} · Exchanges: ${ST.earth.exchanges}</p>`)}
  ${plate('EARTH–001–COSMOS', `<p style="font-size:13.5px;margin:0">${esc((ST.archives.find(a => a.ref === 'EARTH–001–COSMOS') || {body:''}).body)}</p>`)}</div></div></div>`;
};

/* ---------- 13. Rungta Global ---------- */
SCREENS.rungta = () => {
  const R = ST.rg; const last = R.hist[R.hist.length - 1] || {revenue:0, profit:0};
  const ch = R.hist.length > 1 ? lineChart([{name:'Cash (USD M)', color:'#D4AF37', area:true, data:R.hist.map(h => [h.day, h.cash])}, {name:'Monthly revenue', color:'#62C893', data:R.hist.map(h => [h.day, h.revenue])}], {h:170, label:'Rungta Global cash and revenue', fmt:v => '$' + fmt(v)}) : '<div class="empty">Monthly results appear at the end of each month.</div>';
  return `<div class="screen">${head('Rungta Global', 'Founder and Chairman: ' + esc(ST.canon.sovereign), `An Earthly business group headquartered at ${esc(R.hq)}. Its finances, institutions and governance are entirely separate from the Cosmos. Figures in US dollars (millions).`, `<button class="btn" data-act="rgReport">Financial report</button>`)}
  <div class="plate flat" style="padding:10px 14px;border-color:rgba(71,118,230,.4)"><b>Separate governance.</b> <span class="muted" style="font-size:13px">Cosmic Credits cannot fund Rungta Global, and cosmic authority does not override Earthly laws or corporate agreements. Corporate crises are paid from corporate cash.</span></div>
  ${plate('', `<div class="statline"><div><small>Cash</small><b>${fmtUSD(R.cash)}</b></div><div><small>Last month revenue</small><b>${fmtUSD(last.revenue)}</b></div><div><small>Last month profit</small><b class="good">${fmtUSD(last.profit)}</b></div><div><small>Reputation</small><b>${fmt(R.reputation)}/100</b></div><div><small>Markets</small><b>${R.markets.length}</b></div><div><small>India Express</small><b>${R.subsidiaries.find(s => s.id === 'tie').units} restaurants</b></div></div>`)}
  <div class="grid g-side">${plate('Subsidiaries', `<div class="tablewrap"><table><thead><tr><th>Company</th><th>Sector</th><th class="r">Scale</th><th class="r">Rating</th><th class="r">Revenue / mo</th></tr></thead><tbody>${R.subsidiaries.map(s => `<tr><td><b>${esc(s.name)}</b></td><td style="font-size:12.5px">${esc(s.sector)}</td><td class="r">${s.units} ${esc(s.unitLabel)}</td><td class="r">${s.rating.toFixed(2)}</td><td class="r">${fmtUSD(s.lastRev || 0)}</td></tr>`).join('')}</tbody></table></div><div class="sep"></div>${ch}`)}
  <div class="stack" style="gap:14px">${plate('Board meeting', `<div class="stack" style="gap:6px">${RG_AGENDA.map(a => `<div class="spread"><span style="font-size:13px">${esc(a.label)}<br><span class="faint" style="font-size:11.5px">${fmtUSD(a.cost)}${a.days ? ` · ${a.days} days` : ''}</span></span><button class="btn sm" data-act="rgBoard" data-key="${a.key}">Approve</button></div>`).join('')}</div><div class="sep"></div><div class="row" style="align-items:flex-end"><label class="f" style="flex:1">International expansion ($220M)<select id="rgMarket">${R.expansionTargets.map(m => `<option>${esc(m)}</option>`).join('')}</select></label><button class="btn sm primary" data-act="rgIntl" ${R.expansionTargets.length ? '' : 'disabled'}>Expand</button></div>${R.projects.length ? `<div class="sep"></div><div class="eyebrow">Under way</div>${R.projects.map(p => `<p style="font-size:12.5px;margin:4px 0">${esc(p.label)} · completes ${esc(fmtDateShort(p.end))}</p>`).join('')}` : ''}`)}
  ${plate('Executive appointments', `${R.executives.map(e => `<div class="spread" style="padding:4px 0;font-size:13px"><span><b>${esc(e.name)}</b><br><span class="muted" style="font-size:12px">${esc(e.role)} · skill ${e.skill}</span></span></div>`).join('')}<div class="sep"></div><div class="grid g2"><label class="f">Role<select id="rgRole">${R.executives.map(e => `<option>${esc(e.role)}</option>`).join('')}</select></label><label class="f">Candidate<select id="rgCand">${RG_CANDIDATES.map(c => `<option value="${esc(c.name)}">${esc(c.name)} (${c.skill}, ${esc(c.trait)})</option>`).join('')}</select></label></div><button class="btn sm primary" style="margin-top:8px" data-act="rgAppoint">Appoint</button>`)}
  ${plate('Board minutes', R.board.length ? `<div class="muted" style="font-size:12.5px">${R.board.slice(0, 8).map(b => `${esc(fmtDateShort(b.day))}: ${esc(b.text)}`).join('<br>')}</div>` : '<div class="empty">No board decisions yet.</div>')}</div></div></div>`;
};

/* ---------- 14. Cosmic Archives ---------- */
SCREENS.archives = () => {
  const tab = UI.tab.archives || 'records';
  const q = (UI.filter.arq || '').toLowerCase(), t = UI.filter.art || '';
  const types = {history:'History', petition:'Petitions', verdict:'Verdicts', law:'Laws', project:'Projects', event:'Events', decision:'Decisions'};
  const recs = ST.archives.filter(a => (!t || a.type === t) && (!q || (a.title + ' ' + a.body + ' ' + a.ref).toLowerCase().includes(q))).slice(0, 150);
  const docs = ST.documents.filter(d => !q || (d.title + ' ' + d.body).toLowerCase().includes(q)).slice(0, 150);
  return `<div class="screen">${head('Cosmic Archives', 'The Record of the Crowned Era', `${ST.archives.length} records and ${ST.documents.length} official documents.`)}
  <div class="tabs">${[['records', 'Historical records'], ['docs', 'Official documents']].map(([k, l]) => `<button aria-selected="${tab === k}" data-act="tab" data-scr="archives" data-tab="${k}">${l}</button>`).join('')}</div>
  <div class="row"><label class="f" style="flex:2 1 220px">Search<input type="search" id="arSearch" data-inp="arSearch" value="${esc(UI.filter.arq || '')}" placeholder="Title, reference or text"></label>${tab === 'records' ? `<label class="f" style="flex:1 1 160px">Type<select data-chg="arType" id="arType"><option value="">All</option>${Object.entries(types).map(([k, l]) => `<option value="${k}" ${t === k ? 'selected' : ''}>${l}</option>`).join('')}</select></label>` : ''}</div>
  ${tab === 'records' ? plate('', recs.length ? `<div class="list">${recs.map(a => `<div class="li"><div style="flex:none;width:92px"><div class="mono faint" style="font-size:11px">${esc(fmtDateShort(a.day))}</div><span class="pill" style="margin-top:4px">${esc(types[a.type] || a.type)}</span></div><div class="grow"><h4>${esc(a.title)} ${a.ref ? `<span class="mono goldt" style="font-weight:400">${esc(a.ref)}</span>` : ''}</h4><p>${esc(a.body)}</p></div></div>`).join('')}</div>` : '<div class="empty">No records match.</div>')
  : plate('', docs.length ? `<div class="tablewrap"><table><thead><tr><th>Ref.</th><th>Type</th><th>Title</th><th>Date</th></tr></thead><tbody>${docs.map(d => `<tr class="click" data-act="doc" data-id="${d.id}"><td class="mono">${d.id}</td><td>${esc(DOC_LABEL[d.type] || d.type)}</td><td>${esc(d.title)}</td><td>${esc(fmtDateShort(d.day))}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No documents yet. Verdicts, laws, letters, reports and minutes appear here.</div>')}</div>`;
};

/* ---------- 15. Emergency Operations ---------- */
SCREENS.emergency = () => {
  const cr = activeCrises(), past = ST.events.filter(e => e.kind === 'crisis' && e.status !== 'active').slice().reverse();
  const avail = councilMembers(ST).filter(m => memberAvailable(ST, m));
  const card = e => {
    const T = CRISIS_TPL[e.tpl]; const sel = UI.sel['mem-' + e.id];
    const civ = civById(ST, e.civ);
    const opts = T.options.map(o => {
      const best = o.tag ? (avail.find(m => (m.tags || []).includes(o.tag)) || avail[0]) : null;
      const mid = o.tag ? (sel && avail.some(m => m.id === sel) ? sel : best && best.id) : null;
      const p = crisisChance(ST, e, o, mid);
      const blocked = o.tag && !avail.length;
      const mon = o.resolve === 'delay' && e.monitored[e.stage];
      return `<div class="plate flat" style="padding:10px 12px"><div class="spread"><b style="font-size:13.5px">${esc(o.label)}</b><span class="num ${p >= 0.6 ? 'good' : p >= 0.4 ? 'warn' : 'bad'}" style="font-size:12.5px">${o.resolve === 'delay' ? 'Certain' : Math.round(p * 100) + '% success'}</span></div><p class="muted" style="font-size:12.5px;margin:3px 0 6px">${esc(o.detail)}</p><div class="row" style="justify-content:space-between">${o.cost ? `<span class="pill warn">${fmtCC(o.cost)}</span>` : '<span class="pill">No cost</span>'}${o.tag ? `<select data-chg="crisisMember" data-id="${e.id}" id="cm-${e.id}-${o.key}" aria-label="Lead for ${esc(o.label)}" style="font-size:12px">${avail.map(m => `<option value="${m.id}" ${m.id === mid ? 'selected' : ''}>${esc(m.name)}${(m.tags || []).includes(o.tag) ? ' ★' : ''}</option>`).join('') || '<option>No one available</option>'}</select>` : ''}<button class="btn sm ${o.resolve === 'delay' ? '' : 'danger'}" data-act="crisis" data-id="${e.id}" data-key="${o.key}" data-mid="${mid || ''}" ${blocked || mon ? 'disabled' : ''}>${o.resolve === 'delay' ? (mon ? 'Used this stage' : 'Order') : 'Deploy'}</button></div></div>`;
    }).join('');
    const days = e.nextEsc - ST.day;
    return plate(esc(e.title), `<div class="row" style="margin:-6px 0 10px"><span class="mono goldt">${e.id}</span><span class="pill">${esc(civ ? civ.name : '')}</span><span class="stagepips">${[1,2,3,4].map(i => `<i class="${i <= e.stage ? 'on' : ''}"></i>`).join('')}</span><span class="${days <= 5 ? 'bad' : 'warn'}" style="font-size:12.5px">Stage ${e.stage}: ${esc(T.stages[e.stage - 1])} Escalates ${days <= 0 ? 'today' : `in ${days} days`}.</span></div><p style="font-size:13.5px;margin-top:0">${esc(e.desc)}</p><div class="grid g2">${opts}</div><p class="faint" style="font-size:12px">★ marks members whose ability fits the response. Deployed members are unavailable for 10 days. Responses draw on the emergency reserve first.</p><div class="sep"></div><div class="muted" style="font-size:12px">${e.log.slice(-4).map(esc).join('<br>')}</div>`);
  };
  return `<div class="screen">${head('Emergency Operations', 'Crisis Command', 'Emergencies escalate through four stages. Unresolved, they end in catastrophe.', `<button class="btn" data-act="meeting">Convene the Council</button>`)}
  ${plate('', `<div class="statline"><div><small>Active emergencies</small><b class="${cr.length ? 'bad' : ''}">${cr.length}</b></div><div><small>Emergency reserve</small><b>${fmtCC(ST.treasury.reserve)}</b></div><div><small>General balance</small><b>${fmtCC(ST.treasury.balance)}</b></div><div><small>Members available</small><b>${avail.length} of ${councilMembers(ST).length - 1}</b></div><div><small>Resolved this reign</small><b>${ST.stats.crisesResolved}</b></div></div><div class="row" style="margin-top:12px;align-items:flex-end"><label class="f" style="flex:0 1 200px">Allocate to reserve (CC M)<input type="number" min="1" step="50" id="reserveAmt2" value="500"></label><button class="btn" data-act="toReserve2">Allocate emergency funds</button></div>`)}
  ${cr.length ? cr.map(card).join('') : plate('', '<div class="empty">No active emergencies.</div>')}
  ${plate('Emergency record', past.length ? past.slice(0, 12).map(e => `<div class="li"><span class="mono goldt">${e.id}</span><div class="grow"><h4>${esc(e.title)}</h4><p>${esc(e.log[e.log.length - 1] || '')}</p></div>${statusPill(e.status)}</div>`).join('') : '<div class="empty">No emergencies have ended yet.</div>')}</div>`;
};

/* ---------- 16. Sovereign’s Private Office ---------- */
SCREENS.office = () => {
  const tab = UI.tab.office || 'office';
  const tabs = [['office', 'The Office'], ['relations', 'Relationships & memory'], ['command', 'Command console'], ['canon', 'Canon management']];
  let body = '';
  if (tab === 'office') {
    const rs = ST.rise ? riseStatus(ST) : null;
    body = `<div class="grid g-side"><div class="stack" style="gap:14px">${plate('', `<div class="row" style="gap:18px;align-items:center">${sealSVG(110, true)}<div style="min-width:0"><div class="eyebrow">${esc(sovTitle(ST))}</div><h2 style="font-size:32px;color:var(--pearl)">${esc(ST.canon.sovereign)}</h2><p class="muted" style="margin:4px 0 0">Seat of power: the Central Cosmic Throne, Aurelia. Principal adviser: the Prime Arbiter, ${esc(ST.canon.arbiterRole)}.</p></div></div><div class="sep"></div><div class="eyebrow">Regalia of authority</div><ul style="font-size:13.5px;padding-left:18px;margin:6px 0 0"><li>The Constellation Crown</li><li>The Cosmic Staff</li><li>The Central Cosmic Throne</li><li>The Official Cosmic Seal</li><li>The Sovereign’s Constitutional Authority${ST.rise && !ST.rise.crowned ? ' <span class="pill warn">not yet conferred</span>' : ''}</li></ul>`, {cls:'hero'})}
    ${rs ? plate('Rise to the Throne', `<p style="margin-top:0;font-size:13.5px">${ST.rise.crowned ? `Recognised as Sovereign on ${esc(fmtDate(ST.rise.day))}.` : 'Recognition must be unanimous: every member of the Tribunal at trust 70 or higher, and every member civilisation at relation 60 or higher.'}</p><div class="grid g2"><div><div class="spread" style="font-size:12.5px"><span>The Twelve</span><span class="num">${rs.jEnd} / ${rs.jTotal}</span></div>${meter(rs.jEnd / rs.jTotal * 100)}</div><div><div class="spread" style="font-size:12.5px"><span>Member civilisations</span><span class="num">${rs.cEnd} / ${rs.cTotal}</span></div>${meter(rs.cEnd / rs.cTotal * 100)}</div></div>${ST.rise.crowned ? '' : `<div class="btnrow" style="margin-top:10px"><button class="btn primary" data-act="recognition">Petition for recognition</button></div>`}`) : ''}
    ${plate('Campaign', `<dl class="kv"><dt>Mode</dt><dd>${esc(MODE_NAMES[ST.meta.mode])}${ST.meta.creative ? ' <span class="pill purple">Creative: achievements disabled</span>' : ''}</dd><dt>Objective</dt><dd>${esc(ST.goal)}</dd><dt>Reign</dt><dd>${fmt(ST.day)} days · ${ST.stats.verdicts} verdicts · ${ST.stats.lawsEnacted} instruments · ${ST.stats.projectsDone} projects · ${ST.stats.treaties} treaties · ${ST.stats.crisesResolved} emergencies resolved</dd><dt>Seed</dt><dd class="mono">${ST.meta.seed}</dd></dl>`)}</div>
    <div class="stack" style="gap:14px">${plate('Achievements', ACHIEVEMENTS.map(a => `<div class="li"><span class="goldt" style="font-size:16px">${ST.achievements[a.key] !== undefined ? '◆' : '◇'}</span><div class="grow"><h4>${esc(a.name)}</h4><p>${esc(a.desc)}${ST.achievements[a.key] !== undefined ? ` · earned ${esc(fmtDateShort(ST.achievements[a.key]))}` : ''}</p></div></div>`).join('') + (ST.meta.creative ? '<p class="faint" style="font-size:12px">Achievements are disabled in Creative Mode.</p>' : ''))}
    ${plate('Private journal', `<textarea id="journal" data-inp="journal" style="width:100%;min-height:150px" placeholder="Private notes. Saved with the campaign.">${esc(ST.journal)}</textarea>`)}</div></div>`;
  } else if (tab === 'relations') {
    const mem = st => st.chars.flatMap(c => c.memory.slice(0, 6).map(m => Object.assign({who:c.name}, m))).sort((a, b) => b.day - a.day).slice(0, 30);
    body = `<div class="grid g2">${plate('The Twelve', barList(judges(ST).map(j => ({label:`${j.name}${j.standing ? ` (vindicated ${j.standing}×)` : ''}`, v:j.trust, cls:indClass(j.trust)})), {fmt:v => fmt(v)}))}${plate('The Council', barList(councilMembers(ST).filter(m => !m.sovereign).map(m => ({label:m.name, v:m.trust, cls:indClass(m.trust)})), {fmt:v => fmt(v)}))}</div>
    ${plate('What your advisers remember', mem(ST).length ? `<div class="tablewrap"><table><thead><tr><th>Date</th><th>Adviser</th><th>Matter</th><th>Advice</th><th>Followed</th><th>Outcome</th></tr></thead><tbody>${mem(ST).map(m => `<tr><td>${esc(fmtDateShort(m.day))}</td><td>${esc(m.who)}</td><td style="font-size:12.5px">${esc(m.topic)}</td><td>${esc(m.advice)}</td><td>${m.followed ? '<span class="good">Yes</span>' : '<span class="warn">No</span>'}</td><td>${m.resolved ? (m.resolved === 'bad' ? '<span class="bad">Poor</span>' : '<span class="good">Good</span>') : '<span class="faint">—</span>'}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">Advisers remember every recommendation you accept or set aside.</div>')}`;
  } else if (tab === 'command') {
    body = plate('Sovereign’s command console', `<p class="muted" style="margin-top:0;font-size:13px">Type an instruction in plain language. Supported instructions become real game actions; consequential ones show a preview first. Unsupported instructions are explained, never faked.</p><div class="row"><input type="text" id="cmdConsole" style="flex:1" placeholder="e.g. Allocate 200 to research"><button class="btn primary" data-act="cmdConsole">Issue</button></div><div class="sep"></div><div class="eyebrow">Supported instructions</div><div class="chips" style="margin-top:6px">${CMD_EXAMPLES.map(x => `<button class="btn sm ghost" data-act="cmdExample" data-t="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="sep"></div><div class="eyebrow">History</div>${ST.cmdLog.length ? `<div style="font-size:12.5px" class="stack">${ST.cmdLog.slice(0, 30).map(c => `<div><span class="faint">${esc(fmtDateShort(c.day))}</span> <b>${esc(c.text)}</b><br><span class="${c.ok ? 'good' : 'warn'}">${esc(c.result)}</span></div>`).join('')}</div>` : '<p class="faint">No commands issued yet.</p>'}`);
  } else {
    const C = ST.canon;
    body = plate('Canon management', `<p class="muted" style="margin-top:0;font-size:13px">Earlier versions of the Cosmic World described other leadership arrangements. The default follows the most recent canon: a Sovereign advised by the Prime Arbiter. Changes here affect titles in documents and briefings; they do not rewrite archived history.</p><div class="grid g2"><label class="f">Sovereign’s name<input type="text" id="canSov" value="${esc(C.sovereign)}"></label><label class="f">Sovereign’s title<input type="text" id="canTitle" value="${esc(C.title)}"></label><label class="f">Leadership arrangement<select id="canArr">${[['sovereign-arbiter', 'Sovereign with Prime Arbiter as principal adviser (current canon)'], ['co-presiding', 'Sovereign and Prime Arbiter co-presiding over the Tribunal (earlier canon)'], ['council-led', 'Council-led Crown with the Sovereign as first among equals (earlier canon)']].map(([k, l]) => `<option value="${k}" ${C.arrangement === k ? 'selected' : ''}>${l}</option>`).join('')}</select></label><label class="f">Prime Arbiter’s role<input type="text" id="canArb" value="${esc(C.arbiterRole)}"></label><label class="f">Earth’s next collective petition (year)<input type="number" id="canEarth" min="1" max="100000" value="${C.earthNextCollective}"></label></div><div class="btnrow" style="margin-top:12px"><button class="btn primary" data-act="saveCanon">Save canon</button><button class="btn ghost" data-act="resetCanon">Restore default canon</button></div>`);
  }
  return `<div class="screen">${head('Sovereign’s Private Office', 'The Private Office', 'Regalia, relationships, commands and the record of your reign.')}
  <div class="tabs" role="tablist">${tabs.map(([k, l]) => `<button role="tab" aria-selected="${tab === k}" data-act="tab" data-scr="office" data-tab="${k}">${l}</button>`).join('')}</div>${body}</div>`;
};

/* ---------- 17. Settings and Save Management ---------- */
const ROADMAP = [
  ['Phase I · Playable foundation', 'Complete', 'Dashboard, navigation, central game state, cosmic calendar, petitions with consequences, treasury and budget, autosave, manual slots, JSON export and import.'],
  ['Phase II · Governance', 'Complete', 'Nine-stage Tribunal hearings, Council meetings, appointments, departments, committees and delegation, character relationships, laws with constitutional review, official documents.'],
  ['Phase III · Universe expansion', 'Complete', 'Interactive universe map, civilisation dossiers, multi-round diplomacy, research tracks, COSMOS–EDU programme, development projects.'],
  ['Phase IV · Earthly integration', 'Complete', 'Earth Affairs, DAIS and COSMOS–EDU, Rungta Global with separate finances, The India Express.'],
  ['Phase V · Advanced simulation', 'Complete (first version)', 'Procedural events and emergencies, natural-language commands, adviser memory, five campaign modes, Creative world editor, generated audio.'],
  ['Scenario Studio', 'Complete', 'Custom scenarios with starting conditions, scripted and branching story beats, win and lose conditions; live controls for rules, pace and values in any campaign.'],
  ['Planned', 'Not built yet', 'Optional AI-written dialogue, multi-year council elections, deeper Rungta Global market simulation, character portraits beyond symbolic sigils, multiplayer councils.']
];
SCREENS.settings = () => {
  const slots = SaveManager.list().sort((a, b) => b.saved - a.saved);
  const ok = SaveManager.ok();
  const confirmReset = UI.confirmReset;
  return `<div class="screen">${head('Settings and Save Management', 'Campaigns and Preferences', ok ? 'Campaigns are stored in this browser. Export JSON regularly as a reliable backup.' : 'Browser storage is unavailable here. Use Export JSON to keep your progress.')}
  <div class="grid g2">${plate('Save slots', `<div class="row" style="align-items:flex-end"><label class="f" style="flex:1">Save name<input type="text" id="saveName" value="${esc(MODE_NAMES[ST.meta.mode])} · ${esc(fmtDateShort(ST.day))}"></label><button class="btn primary" data-act="saveNew" ${ok ? '' : 'disabled'}>Save to new slot</button></div>
    ${slots.length ? `<div class="tablewrap" style="margin-top:10px"><table><thead><tr><th>Name</th><th>Campaign date</th><th>Saved</th><th></th></tr></thead><tbody>${slots.map(s => `<tr><td><b>${esc(s.name)}</b><br><span class="faint" style="font-size:11.5px">${esc(MODE_NAMES[s.mode] || s.mode)} · ${Math.round(s.size / 1024)} KB</span></td><td>${esc(fmtDateShort(s.day))}</td><td style="font-size:12px">${esc(new Date(s.saved).toLocaleString())}</td><td><div class="btnrow"><button class="btn sm" data-act="loadSlot" data-id="${s.id}">Load</button>${s.id !== 'autosave' ? `<button class="btn sm" data-act="overwriteSlot" data-id="${s.id}" data-name="${esc(s.name)}">Overwrite</button>` : ''}<button class="btn sm danger" data-act="deleteSlot" data-id="${s.id}" data-name="${esc(s.name)}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No saved campaigns yet.</div>'}
    <label class="row" style="margin-top:10px;font-size:13px;gap:8px"><input type="checkbox" data-chg="pref" data-k="autosave" id="pAutosave" ${PREFS.autosave ? 'checked' : ''}> Autosave after every action and each month${UI.lastAutosave ? ` <span class="faint">(last ${esc(new Date(UI.lastAutosave).toLocaleTimeString())})</span>` : ''}</label>`)}
  ${plate('Export and import', `<p class="muted" style="margin-top:0;font-size:13px">Downloads are blocked inside this viewer, so export copies the full campaign as JSON. Paste it into a text file to keep it.</p><div class="btnrow"><button class="btn primary" data-act="exportJson">Copy campaign JSON</button><button class="btn" data-act="showJson">Show JSON</button></div><div class="sep"></div><label class="f">Import from a file<input type="file" id="importFile" accept=".json,application/json,text/plain"></label><label class="f" style="margin-top:8px">Or paste campaign JSON<textarea id="importText" placeholder='{"meta":{...}}' style="min-height:90px"></textarea></label><button class="btn" style="margin-top:8px" data-act="importJson">Import campaign</button><p class="faint" style="font-size:12px">Importing replaces the current campaign. Your current campaign is saved to the autosave slot first.</p>`)}</div>
  <div class="grid g2">${plate('New campaign', `<div class="stack">${Object.entries(MODE_NAMES).map(([k, l]) => `<label class="row" style="gap:8px;align-items:flex-start;font-size:13.5px;cursor:pointer"><input type="radio" name="newMode" value="${k}" id="nm-${k}" ${k === 'sandbox' ? 'checked' : ''}><span><b>${l}</b><br><span class="muted" style="font-size:12.5px">${{sandbox:'The main open-ended campaign as the established Sovereign.', rise:'Begin as a candidate and earn the unanimous recognition of the Twelve and the member civilisations.', crisis:'A universe facing interconnected political, environmental and economic emergencies.', tribunal:'A judicial simulation focused on hearings, evidence and verdicts.', creative:'Unrestricted world-building. Achievements are disabled.'}[k]}</span></span></label>`).join('')}<label class="f">Seed (optional, for a reproducible campaign)<input type="number" id="newSeed" placeholder="Random"></label><button class="btn primary" data-act="newCampaign">Start new campaign</button><p class="faint" style="font-size:12px">The current campaign is saved to the autosave slot before a new one begins.</p></div>`)}
  <div class="stack" style="gap:14px">${plate('Audio', `<label class="row" style="gap:8px;font-size:13px"><input type="checkbox" data-chg="pref" data-k="muted" id="pMuted" ${PREFS.muted ? 'checked' : ''}> Mute all sound</label>${[['master', 'Master volume'], ['music', 'Ambient music and chamber'], ['sfx', 'Notifications and interface']].map(([k, l]) => `<label class="f" style="margin-top:8px">${l}<input type="range" min="0" max="1" step="0.05" value="${PREFS[k]}" data-chg="pref" data-k="${k}" id="p-${k}"></label>`).join('')}<p class="faint" style="font-size:12px">All audio is generated in the browser. Sound starts only after you unmute.</p>`)}
  ${plate('Display', `<label class="row" style="gap:8px;font-size:13px"><input type="checkbox" data-chg="pref" data-k="big" id="pBig" ${PREFS.big ? 'checked' : ''}> Larger text</label><label class="row" style="gap:8px;font-size:13px;margin-top:6px"><input type="checkbox" data-chg="pref" data-k="calm" id="pCalm" ${PREFS.calm ? 'checked' : ''}> Reduce motion</label><div class="btnrow" style="margin-top:10px"><button class="btn sm ghost" data-act="replayIntro">Replay opening scene</button></div>`)}
  ${plate('Reset campaign', confirmReset ? `<p class="bad" style="margin-top:0">This restarts the current ${esc(MODE_NAMES[ST.meta.mode])} campaign from day 0. The current state is saved to the autosave slot first.</p><div class="btnrow"><button class="btn danger" data-act="resetYes">Yes, reset the campaign</button><button class="btn" data-act="resetNo">Cancel</button></div>` : `<div class="btnrow"><button class="btn danger" data-act="resetAsk">Restart this campaign…</button><button class="btn danger" data-act="resetAllAsk">Erase everything and start fresh…</button></div>`)}</div></div>
  ${plate('Development status', `<div class="tablewrap"><table><tbody>${ROADMAP.map(([p, s, d]) => `<tr><td style="white-space:nowrap"><b>${esc(p)}</b></td><td><span class="pill ${s.startsWith('Complete') ? 'good' : 'warn'}">${esc(s)}</span></td><td style="font-size:12.5px">${esc(d)}</td></tr>`).join('')}</tbody></table></div>`)}</div>`;
};

